package service

import (
	"reflect"
	"runtime"
	"slices"
)

// unimplementedType is the name of the generated struct whose methods answer
// 501 for every operation. A provider embeds it.
const unimplementedType = "Unimplemented"

// autogenerated is the file the Go runtime reports for a method the compiler
// wrote: the wrapper that promotes an embedded type's method, or that gives a
// pointer the methods of its value.
const autogenerated = "<autogenerated>"

// method is what a handler's method turned out to be.
type method int

const (
	// unclassified is a method the check cannot place, so the service's
	// implemented operations are unknown.
	unclassified method = iota
	// declared is a method the handler's own code declares: an implemented
	// operation.
	declared
	// unimplemented is the generated Unimplemented's method, reached through
	// embedding: the operation answers 501.
	unimplemented
)

// lookup returns the method of a type that implements an operation: a
// [Metadata.OperationMethod].
type lookup = func(t reflect.Type, operation string) (reflect.Method, bool)

// Implemented returns the operations, out of operations, that handler declares
// itself rather than reaching through the generated Unimplemented it embeds. It
// returns ok false, and no operations, when handler or operationMethod is nil
// or when any of handler's methods cannot be classified, so a count is never a
// guess.
//
// It uses reflection, once per service when the capabilities are first asked
// for, never on a call. Every method is looked up through operationMethod, the
// generated OperationMethod, which names each method with a constant: a lookup
// by a variable name would make the linker keep every exported method of the
// binary. A method the compiler promoted from an embedded type is a wrapper
// whose file the runtime reports as "<autogenerated>"; the check follows such a
// wrapper down the embedded fields to the method it reaches, taking the field
// that reaches it at the shallowest depth as Go does, and counts the operation
// as unimplemented when that method is declared on a type named Unimplemented,
// as the generated one is. A method that reaches an embedded interface, which
// holds code the check cannot see, is unclassified, so a handler that wraps
// another handler reports its operations as unknown. The tests of cmd/gostack pin the
// counts of the registered services, so a toolchain that reports wrappers
// differently fails them.
func Implemented(handler any, operations []string, operationMethod lookup) (implemented []string, ok bool) {
	if handler == nil || operationMethod == nil {
		return nil, false
	}

	t := reflect.TypeOf(handler)
	implemented = []string{}

	for _, operation := range operations {
		switch classify(operationMethod, t, operation, nil).kind {
		case declared:
			implemented = append(implemented, operation)
		case unimplemented:
		default:
			return nil, false
		}
	}

	return implemented, true
}

// placement is where the method of a type for an operation turned out to be.
type placement struct {
	kind method

	// depth is how many embedded fields the method is reached through, as Go
	// counts them: a method the type declares is at depth 0.
	depth int
}

// classify places the method of t for operation. path is the struct types the
// walk is inside, outermost first.
func classify(operationMethod lookup, t reflect.Type, operation string, path []reflect.Type) placement {
	m, found := operationMethod(t, operation)
	if !found {
		return placement{kind: unclassified}
	}

	// The method of an interface, which is what an embedded interface field
	// promotes, has no function: the code behind it is whatever the field holds.
	if !m.Func.IsValid() {
		return placement{kind: unclassified}
	}

	fn := runtime.FuncForPC(m.Func.Pointer())
	if fn == nil {
		return placement{kind: unclassified}
	}

	file, _ := fn.FileLine(fn.Entry())

	switch {
	case file == "":
		return placement{kind: unclassified}
	case file != autogenerated && named(t) == unimplementedType:
		return placement{kind: unimplemented}
	case file != autogenerated:
		return placement{kind: declared}
	default:
		return promoted(operationMethod, t, operation, path)
	}
}

// promoted places the method of t for operation that the compiler wrote: a
// pointer's method reached through its value, or a struct's method reached
// through an embedded field. Go selects the field that reaches the method at
// the shallowest depth, and promoted does too. Two fields at the same depth are
// ambiguous, which Go leaves out of the method set; they are not placed.
//
// A struct may embed a pointer to its own type, or two structs may embed each
// other. The walk skips an embedded field whose type is a struct it is already
// inside: its method set adds nothing the outer visit has not found, and
// following it would never end. Each call gets its own copy of path, so two
// sibling fields do not see each other's.
func promoted(operationMethod lookup, t reflect.Type, operation string, path []reflect.Type) placement {
	addressable := t.Kind() == reflect.Pointer
	if addressable {
		t = t.Elem()

		if _, found := operationMethod(t, operation); found {
			return classify(operationMethod, t, operation, path)
		}
	}

	if t.Kind() != reflect.Struct {
		return placement{kind: unclassified}
	}

	path = append(slices.Clip(path), t)

	var (
		best   placement
		seen   bool
		shared bool
	)

	for field := range t.Fields() {
		if !field.Anonymous {
			continue
		}

		fieldType := field.Type
		if addressable && fieldType.Kind() != reflect.Pointer {
			fieldType = reflect.PointerTo(fieldType)
		}

		if _, found := operationMethod(fieldType, operation); !found {
			continue
		}

		if onPath(path, fieldType) {
			continue
		}

		at := classify(operationMethod, fieldType, operation, path)
		at.depth++

		switch {
		case !seen || at.depth < best.depth:
			best, seen, shared = at, true, false
		case at.depth == best.depth:
			shared = true
		default:
			// Deeper than the best so far: Go does not select it.
		}
	}

	if !seen || shared {
		return placement{kind: unclassified}
	}

	return best
}

// onPath reports whether t, or what t points to, is one of the types in path.
func onPath(path []reflect.Type, t reflect.Type) bool {
	if t.Kind() == reflect.Pointer {
		t = t.Elem()
	}

	return slices.Contains(path, t)
}

// named returns the name of t, or of what t points to.
func named(t reflect.Type) string {
	if t.Kind() == reflect.Pointer {
		t = t.Elem()
	}

	return t.Name()
}
